<script setup lang="ts">
import { computed, nextTick, onMounted, reactive, ref } from 'vue'
import { useRoute } from 'vue-router'
import { ElMessage, ElMessageBox } from 'element-plus'
import { api } from '../api'
import SalesOrderPrint from '../components/SalesOrderPrint.vue'
const rows=ref<any[]>([]),customers=ref<any[]>([]),products=ref<any[]>([]),categories=ref<any[]>([]),salespeople=ref<any[]>([]),loading=ref(false),dialog=ref(false),productId=ref<number|null>(null)
const productParentId=ref<number|null>(null),productCategoryId=ref<number|null>(null),productKeyword=ref(''),productLoading=ref(false),customerLoading=ref(false)
const detailDialog=ref(false),detailLoading=ref(false),detail=ref<any>(null)
const inlineDetail=ref<any>(null),inlineDetailLoading=ref(false),selectedOrderId=ref<number|null>(null)
const printSettingsDialog=ref(false)
const printSettings=reactive({formatVersion:2,companyName:'',paperSize:'CONTINUOUS_241_140' as 'CONTINUOUS_241_140'|'A4'|'A5',orientation:'landscape' as 'portrait'|'landscape',showPhone:true,showPrice:true,showRemark:true})
const editingId=ref<number|null>(null),editingVersion=ref(0),copySourceNo=ref(''),customerCode=ref('')
import { localToday } from '../utils/date'
const today=localToday()
const route=useRoute()
const routeValue=(value:unknown)=>Array.isArray(value)?String(value[0]||''):String(value||'')
const allDates=routeValue(route.query.dateScope)==='ALL'
const initialWorkflowStatus=routeValue(route.query.workflowStatus)
const query=reactive({keyword:'',status:'',workflowStatus:initialWorkflowStatus,dateFrom:allDates?'':today,dateTo:allDates?'':today,salesperson:'',recorder:'',settlementMethod:'',minAmount:undefined as number|undefined,maxAmount:undefined as number|undefined,sortBy:'date',sortDirection:'asc',page:1,pageSize:100}),form=reactive({orderDate:localToday(),customerId:null as number|null,salespersonId:null as number|null,settlementMethod:'Cash',remark:'',items:[] as any[]})
const total=computed(()=>form.items.reduce((s,x)=>s+Number(x.quantity||0)*Number(x.unitPrice||0),0))
const selectedCustomer=computed(()=>customers.value.find((x:any)=>x.id===form.customerId)||null)
async function load(){loading.value=true;try{const{data}=await api.get('/sales-orders',{params:query});rows.value=data.data.items}finally{loading.value=false}}
function handleSortChange({prop,order}:{prop:string,order:string}){query.sortBy=prop==='orderNo'?'documentNo':'date';query.sortDirection=order==='descending'?'desc':'asc';query.page=1;load()}
async function focusNewOrder(orderNo:string){await nextTick();const row=Array.from(document.querySelectorAll('.el-table__body-wrapper tbody tr')).find(x=>x.textContent?.includes(orderNo));if(!row)return;row.classList.add('newly-created-row');row.scrollIntoView({behavior:'smooth',block:'center'});window.setTimeout(()=>row.classList.remove('newly-created-row'),5000)}
function resetQuery(){Object.assign(query,{keyword:'',status:'',workflowStatus:'',dateFrom:'',dateTo:'',salesperson:'',recorder:'',settlementMethod:'',minAmount:undefined,maxAmount:undefined,sortBy:'date',sortDirection:'asc',page:1});load()}
const productChildren=computed(()=>categories.value.find(x=>x.id===productParentId.value)?.children||[])
async function searchCustomers(keyword=''){customerLoading.value=true;try{const term=keyword.trim();const{data}=await api.get('/customers',{params:{keyword:term,pageSize:100,enabled:true}});customers.value=data.data.items;if(term){const exact=customers.value.filter((c:any)=>normalizedCode(c.customerCode)===normalizedCode(term));if(exact.length===1)form.customerId=exact[0].id}}finally{customerLoading.value=false}}
function clearCustomerSelection(){form.customerId=null}
async function resolveCustomerCode(){const keyword=customerCode.value.trim();if(!keyword)return;await searchCustomers(keyword);const exactCode=customers.value.find((c:any)=>normalizedCode(c.customerCode)===normalizedCode(keyword));const exactContact=customers.value.filter((c:any)=>[c.phone,c.mobile].some((value:any)=>String(value||'').split(/[\s,, ;; /]+/).some(part=>normalizedCode(part)===normalizedCode(keyword))));const matched=exactCode||(exactContact.length===1?exactContact[0]:customers.value.length===1?customers.value[0]:null);if(!matched){form.customerId=null;return ElMessage.warning(customers.value.length?`Multiple customers found. Enter the full customer code or phone number.`:`No customer found for code or phone “${keyword}”`)}form.customerId=matched.id;customerCode.value=matched.customerCode}
async function loadOptions(){const[,t,e]=await Promise.all([searchCustomers(),api.get('/product-categories/tree'),api.get('/employees',{params:{pageSize:100,enabled:true}})]);categories.value=t.data.data.filter((x:any)=>x.productCount>0&&x.code!=='016');const employeeRows=e.data.data.items||e.data.data;salespeople.value=employeeRows.filter((x:any)=>x.salesperson)}
function normalizedCode(value:any){return String(value??'').trim().toLocaleLowerCase()}
function nullableNumber(value:any){return value===''||value===null||value===undefined?null:Number(value)}
async function searchProducts(addExactMatch=false){productLoading.value=true;try{const keyword=productKeyword.value.trim();const categoryId=keyword?undefined:(productCategoryId.value||productParentId.value||undefined);const{data}=await api.get('/products',{params:{pageSize:100,enabled:true,saleable:true,categoryId,keyword}});products.value=data.data.items;const exact=keyword?products.value.filter((p:any)=>normalizedCode(p.skuCode)===normalizedCode(keyword)):[];productId.value=exact.length===1?exact[0].id:null;if(keyword&&!products.value.length)ElMessage.warning(`No saleable product code or name contains “${keyword}” saleable products`);else if(addExactMatch&&exact.length===1)addProduct();else if(addExactMatch&&products.value.length>0)ElMessage.info('Multiple similar products found. Select one from the results.') }finally{productLoading.value=false}}
async function chooseProductParent(){productCategoryId.value=null;productId.value=null;products.value=[];await searchProducts()}
async function chooseProductCategory(){productId.value=null;products.value=[];await searchProducts()}
function blankItem(){return{skuId:null,skuCode:'',productName:'',packageSpec:null,packageCount:null,packageUnit:'',salesUnit:'',quantity:0,unitPrice:0,referencePrice:0,currentStock:null,remark:'',blank:true}}
function productItem(p:any){const referencePrice=Number(p.wholesalePrice||0);return{skuId:p.id,skuCode:p.skuCode,productName:p.productName,packageSpec:nullableNumber(p.packageSpec),packageCount:null,packageUnit:p.packageUnit||'',salesUnit:p.salesUnit,quantity:0,unitPrice:referencePrice,referencePrice,currentStock:Number(p.totalStock||0),remark:'',blank:false}}
function ensureBlankRow(){if(!form.items.some((x:any)=>!x.skuId))form.items.push(blankItem())}
async function openNew(){await loadOptions();if(!customers.value.length||!categories.value.length)return ElMessage.warning('First Entrytoat least one itemsValidCustomerandavailable SalesProduct');editingId.value=null;editingVersion.value=0;copySourceNo.value='';customerCode.value='';Object.assign(form,{orderDate:localToday(),customerId:null,salespersonId:null,settlementMethod:'Cash',remark:'',items:[blankItem()]});productId.value=null;productParentId.value=null;productCategoryId.value=null;productKeyword.value='';products.value=[];dialog.value=true;await nextTick();(document.querySelector('.customer-code-input input') as HTMLInputElement|null)?.focus()}
function addProduct(){const p=products.value.find(x=>x.id===productId.value);if(!p)return;if(form.items.some(x=>x.skuId===p.id))return ElMessage.warning(`${p.skuCode} Already in Sales Order`);const referencePrice=Number(p.wholesalePrice||0);form.items.push({skuId:p.id,skuCode:p.skuCode,productName:p.productName,packageSpec:nullableNumber(p.packageSpec),packageCount:null,packageUnit:p.packageUnit||'',salesUnit:p.salesUnit,quantity:1,unitPrice:referencePrice,referencePrice,currentStock:Number(p.totalStock||0),remark:''});productId.value=null;productKeyword.value='';products.value=[]}
async function resolveProductCode(row:any,index:number){const code=String(row.skuCode||'').trim();if(!code)return;productLoading.value=true;try{const{data}=await api.get('/products',{params:{pageSize:100,enabled:true,saleable:true,keyword:code}});const matches=data.data.items||[];const exact=matches.find((p:any)=>normalizedCode(p.skuCode)===normalizedCode(code));if(!exact)return ElMessage.warning(`No product found with code “${code}”`);if(form.items.some((x:any,i:number)=>i!==index&&x.skuId===exact.id))return ElMessage.warning(`${exact.skuCode} Already in Sales Order`);Object.assign(row,productItem(exact));ensureBlankRow();await nextTick();(document.querySelectorAll('.quantity-input input')[index] as HTMLInputElement|null)?.focus()}finally{productLoading.value=false}}
async function focusPrice(index:number){await nextTick();(document.querySelectorAll('.unit-price-input input')[index] as HTMLInputElement|null)?.focus()}
async function finishItem(index:number){if(!form.items[index]?.skuId)return;ensureBlankRow();await nextTick();(document.querySelectorAll('.sku-code-input input')[index+1] as HTMLInputElement|null)?.focus()}
function salePriceClass(row:any){return Number(row.unitPrice)>Number(row.referencePrice)?'price-high':Number(row.unitPrice)>0&&Number(row.unitPrice)<Number(row.referencePrice)?'price-low':'price-equal'}
async function save(){const activeItems=form.items.filter((x:any)=>x.skuId);if(!form.customerId||!activeItems.length)return ElMessage.warning('Enter a customer code and add at least one product');const invalidQuantity=activeItems.find(x=>!Number.isFinite(Number(x.quantity))||Number(x.quantity)<0.01||Math.abs(Number(x.quantity)*100-Math.round(Number(x.quantity)*100))>1e-8);if(invalidQuantity)return ElMessage.error(`Quantity must be at least 0.01 and use no more than two decimal places: ${invalidQuantity.skuCode} ${invalidQuantity.productName}`);const negative=activeItems.find(x=>Number(x.unitPrice)<0);if(negative)return ElMessage.error(`Unit price cannot be negative: ${negative.skuCode} ${negative.productName}`);const low=activeItems.find(x=>Number(x.unitPrice)>0&&Number(x.unitPrice)<Number(x.referencePrice));if(low)return ElMessage.error(`Sale price too low: ${low.skuCode} ${low.productName}  unit price cannot be below the reference price ${Number(low.referencePrice).toFixed(2)}`);const payload={...form,items:activeItems};try{let created:any=null;if(editingId.value){await api.put(`/sales-orders/${editingId.value}`,{...payload,version:editingVersion.value});ElMessage.success('Sales order draft updated successfully')}else{const{data}=await api.post('/sales-orders',payload);created=data.data}dialog.value=false;editingId.value=null;const wasCopy=!!copySourceNo.value;copySourceNo.value='';await load();if(created){await focusNewOrder(created.orderNo);ElMessage({type:'success',message:wasCopy?`Copied to New Sales Order ${created.orderNo}, Located and Highlighted`:`Sales Order ${created.orderNo} Created successfully, located and highlighted`,duration:5000,showClose:true})}}catch(e:any){ElMessage.error(e?.response?.data?.message||'Unable to save the sales order. Please try again')}}
function fillFromDetail(d:any,orderDate=d.orderDate){if(!customers.value.some((x:any)=>x.id===d.customerId))customers.value.unshift({id:d.customerId,customerCode:d.customerCode,shortName:d.customerName,phone:d.customerPhone});customerCode.value=d.customerCode;Object.assign(form,{orderDate,customerId:d.customerId,salespersonId:d.salespersonId?Number(d.salespersonId):null,settlementMethod:d.settlementMethod,remark:d.remark,items:[...d.items.map((x:any)=>({skuId:x.skuId,skuCode:x.skuCode,productName:[x.productName,x.specification,x.color].filter(Boolean).join(' '),packageSpec:nullableNumber(x.packageSpec),packageCount:nullableNumber(x.packageCount),packageUnit:x.packageUnit,salesUnit:x.salesUnit,quantity:Number(x.quantity),unitPrice:Number(x.unitPrice),referencePrice:Number(x.referencePrice),currentStock:Number(x.currentStock||0),remark:x.remark,blank:false})),blankItem()]})}
async function editOrder(row:any){await loadOptions();const{data}=await api.get(`/sales-orders/${row.id}`);const d=data.data;editingId.value=d.id;editingVersion.value=d.version;copySourceNo.value='';fillFromDetail(d);dialog.value=true}
async function copyOrder(row:any){await loadOptions();const{data}=await api.get(`/sales-orders/${row.id}`);editingId.value=null;editingVersion.value=0;copySourceNo.value=data.data.orderNo;fillFromDetail(data.data,localToday());dialog.value=true}
async function voidOrder(row:any){if(row.status!=='DRAFT'||row.printedAt)return ElMessage.warning('Approved or printed sales orders cannot be changed');await ElMessageBox.confirm('Are you sure you want to void this document?','Void Sales Order',{confirmButtonText:'Confirm Void',cancelButtonText:'Cancel',type:'warning'});await api.post(`/sales-orders/${row.id}/void`,{version:row.version});ElMessage.success('Voided');await load()}
async function openDetail(row:any){detailLoading.value=true;detailDialog.value=true;try{const{data}=await api.get(`/sales-orders/${row.id}`);detail.value=data.data}finally{detailLoading.value=false}}
async function selectOrder(row:any){selectedOrderId.value=row.id;inlineDetailLoading.value=true;try{const{data}=await api.get(`/sales-orders/${row.id}`);if(selectedOrderId.value===row.id)inlineDetail.value=data.data}finally{if(selectedOrderId.value===row.id)inlineDetailLoading.value=false}}
async function printOrder(){if(!detail.value)return;await nextTick();let style=document.getElementById('sales-print-page-size') as HTMLStyleElement|null;if(!style){style=document.createElement('style');style.id='sales-print-page-size';document.head.appendChild(style)}const size=printSettings.paperSize==='CONTINUOUS_241_140'?'241mm 140mm':printSettings.paperSize;style.textContent=`@page { size: ${size} ${printSettings.orientation}; margin: ${printSettings.paperSize==='CONTINUOUS_241_140'?'5mm':'10mm'}; }`;window.print();try{await confirmPrintSuccess()}catch(e:any){if(e==='cancel'||e==='close')return;throw e}}
async function confirmPrintSuccess(){if(!detail.value)return;let reason='';if(detail.value.printedAt){const result=await ElMessageBox.prompt('Enter the reason for this reprint. Reprinting updates the print count but does not deduct stock again.','Confirm Successful Reprint',{inputValidator:v=>!!v||'Reprint reason is required',type:'warning'});reason=result.value}else{await ElMessageBox.confirm('Confirm only after the document has printed successfully or been saved as a PDF. First-print confirmation deducts stock immediately.','Confirm Successful First Print',{confirmButtonText:'Confirm and Deduct Stock',cancelButtonText:'Not Printed Yet',type:'warning'})}const{data}=await api.post(`/sales-orders/${detail.value.id}/confirm-print`,{version:detail.value.version,reason});ElMessage.success(data.data.firstPrint?'Print confirmed and stock deducted':'Reprint recorded; stock was not deducted again');const refreshed=await api.get(`/sales-orders/${detail.value.id}`);detail.value=refreshed.data.data;load()}
function loadPrintSettings(){try{const saved=JSON.parse(localStorage.getItem('sales-order-print-settings')||'{}');Object.assign(printSettings,saved);if(!saved.formatVersion){printSettings.paperSize='CONTINUOUS_241_140';printSettings.orientation='landscape'}}catch{/* Ignore invalid legacy settings */}}
function savePrintSettings(){localStorage.setItem('sales-order-print-settings',JSON.stringify(printSettings));printSettingsDialog.value=false;ElMessage.success('Print SettingsSaved')}
function csvCell(value:any){return `"${String(value??'').replaceAll('"','""')}"`}
function exportOrder(){if(!detail.value)return;const lines=[['Code','Product / Specification','Quantity','Unit','Unit Price','Amount'],...detail.value.items.map((x:any)=>[x.skuCode,[x.productName,x.specification,x.color].filter(Boolean).join(' '),x.quantity,x.salesUnit,x.unitPrice,x.lineAmount])];downloadCsv(`${detail.value.orderNo}-Sales Order.csv`,lines)}
function downloadCsv(name:string,rows:any[][]){const blob=new Blob(['\ufeff'+rows.map(r=>r.map(csvCell).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=name;a.click();URL.revokeObjectURL(url)}
function statusText(row:any){if(row.status==='VOIDED')return 'Voided';const tags=[];if(row.printedAt)tags.push('Printed');if(row.dispatchApproved)tags.push('Approved','Dispatched');else if(row.dispatched)tags.push('Added to Dispatch Sheet');return tags.length?tags.join(' / '):'Ordered'}
function progressStep(row:any){if(row.status==='VOIDED')return -1;if(row.dispatchApproved)return 3;if(row.dispatched)return 2;if(row.printedAt)return 1;return 0}
function orderRowClassName({row}:{row:any}){return row.status==='VOIDED'?'voided-order-row':''}
function printKindText(kind:string){return kind==='FIRST_PRINT'?'First Print':'Reprint'}
onMounted(()=>{loadPrintSettings();load()})
</script>
<template><section><div class="page-heading"><div><h1>Sales Orders</h1><p>Create orders, check inventory, print delivery notes, and track dispatch status.</p></div><el-button type="primary" @click="openNew">Create Sales Order</el-button></div>
<el-card><div class="advanced-search"><div class="search-row"><el-date-picker v-model="query.dateFrom" type="date" value-format="YYYY-MM-DD" placeholder="Start Date"/><span class="date-separator">to</span><el-date-picker v-model="query.dateTo" type="date" value-format="YYYY-MM-DD" placeholder="End Date"/><el-input v-model="query.keyword" clearable placeholder="Sales Order No. / Customer Code / Customer Name" @keyup.enter="load"/><el-input v-model="query.salesperson" clearable placeholder="Salesperson" @keyup.enter="load"/><el-button type="primary" @click="load">Search</el-button><el-button @click="resetQuery">Clear Filters</el-button></div><div class="search-row secondary"><el-input v-model="query.recorder" clearable placeholder="Created By" @keyup.enter="load"/><el-select v-model="query.settlementMethod" clearable placeholder="All Payment Methods"><el-option label="Cash" value="Cash"/><el-option label="Credit" value="Credit"/></el-select><el-input-number v-model="query.minAmount" :min="0" :precision="2" placeholder="Minimum Amount" controls-position="right"/><span class="date-separator">to</span><el-input-number v-model="query.maxAmount" :min="0" :precision="2" placeholder="Maximum Amount" controls-position="right"/></div><el-radio-group v-model="query.workflowStatus" class="workflow-filter" @change="load"><el-radio-button value="">All</el-radio-button><el-radio-button value="UNPRINTED">Not Printed</el-radio-button><el-radio-button value="PRINTED">Printed</el-radio-button><el-radio-button value="UNDISPATCHED">Not Added to Dispatch Sheet</el-radio-button><el-radio-button value="DISPATCHED">Added to Dispatch Sheet</el-radio-button><el-radio-button value="APPROVED">Approved / Dispatched</el-radio-button></el-radio-group><el-checkbox v-model="query.status" true-value="VOIDED" false-value="" class="void-filter" @change="load">Voided Only</el-checkbox></div>
<el-table :data="rows" v-loading="loading" stripe highlight-current-row :row-class-name="orderRowClassName" :default-sort="{prop:'orderDate',order:'ascending'}" @sort-change="handleSortChange" @row-click="selectOrder" @row-dblclick="openDetail"><el-table-column prop="orderNo" label="Sales Order No." width="150" sortable="custom" :sort-orders="['ascending','descending']"/><el-table-column label="Document Progress" width="300"><template #default="s"><div v-if="s.row.status==='VOIDED'" class="order-progress"><el-tag type="danger" effect="dark">Voided</el-tag></div><div v-else class="order-progress"><el-tag :type="progressStep(s.row)>=1?'warning':'info'" :effect="progressStep(s.row)>=1?'dark':'plain'">{{progressStep(s.row)>=1?'✓ Printed':'Not Printed'}}</el-tag><el-tag :type="progressStep(s.row)>=2?'primary':'info'" :effect="progressStep(s.row)>=2?'dark':'plain'">{{progressStep(s.row)>=2?'✓ Added to Dispatch Sheet':'Not Added to Dispatch Sheet'}}</el-tag><el-tag :type="progressStep(s.row)>=3?'success':'info'" :effect="progressStep(s.row)>=3?'dark':'plain'">{{progressStep(s.row)>=3?'✓ Approved/Dispatched':'Not Approved'}}</el-tag></div></template></el-table-column><el-table-column prop="orderDate" label="Date" width="110" sortable="custom" :sort-orders="['ascending','descending']"/><el-table-column prop="customerCode" label="Customer Code" width="105"/><el-table-column prop="customerName" label="Customer Name" min-width="180"/><el-table-column prop="totalAmount" label="Total Amount" width="105"/><el-table-column label="Actions" width="265" fixed="right"><template #default="s"><el-button link type="primary" @click="openDetail(s.row)">Print Preview</el-button><el-button link type="primary" @click="copyOrder(s.row)">Copy Order</el-button><el-button v-if="s.row.status==='DRAFT'&&!s.row.printedAt" link type="primary" @click="editOrder(s.row)">Edit</el-button><el-button v-if="s.row.status!=='VOIDED'&&!s.row.printedAt" link type="danger" @click="voidOrder(s.row)">Void</el-button></template></el-table-column></el-table><div class="inline-detail-panel" v-loading="inlineDetailLoading"><div class="inline-detail-heading"><div><strong>{{inlineDetail?`Sales Order ${inlineDetail.orderNo}  product lines`:'Click a sales order above to view product lines'}}</strong><span v-if="inlineDetail">Double-click a sales order above to open full details</span></div><span v-if="inlineDetail">Total  {{inlineDetail.items?.length||0}}  rows, Total ¥{{Number(inlineDetail.totalAmount||0).toFixed(2)}}</span></div><el-table v-if="inlineDetail" :data="inlineDetail.items" border max-height="300"><el-table-column prop="skuCode" label="Code" width="120"/><el-table-column label="Product / Specification" min-width="260"><template #default="s">{{[s.row.productName,s.row.specification,s.row.color].filter(Boolean).join(' ')}}</template></el-table-column><el-table-column prop="packageCount" label="Packages" width="80"/><el-table-column prop="packageUnit" label="Package Unit" width="100"/><el-table-column prop="quantity" label="Quantity" width="90"/><el-table-column prop="salesUnit" label="Unit" width="80"/><el-table-column prop="unitPrice" label="Unit Price" width="100"/><el-table-column prop="referencePrice" label="Reference Price" width="100"/><el-table-column prop="lineAmount" label="Amount" width="110"/><el-table-column prop="remark" label="Notes" min-width="130"/></el-table><el-empty v-else :image-size="64" description="Please select a sales order"/></div></el-card>
<el-dialog v-model="dialog" :title="editingId?'Edit Sales Order Draft':copySourceNo?`Copy Sales Order ${copySourceNo}`:'Create Sales Order'" width="1200px"><el-alert v-if="copySourceNo" title="The customer and products were copied from the source order. Verify quantities and prices before saving; the new order will not affect the original." type="success" :closable="false" show-icon style="margin-bottom:14px"/><el-form label-width="82px"><el-row :gutter="12"><el-col :span="5"><el-form-item label="Order Date" required><el-date-picker v-model="form.orderDate" type="date" value-format="YYYY-MM-DD" :disabled="!!editingId" style="width:100%"/></el-form-item></el-col><el-col :span="6"><el-form-item label="Customer Code" required><el-input v-model="customerCode" class="customer-code-input" placeholder="Enter a code or phone number and press Enter" :loading="customerLoading" @input="clearCustomerSelection" @keyup.enter="resolveCustomerCode"/></el-form-item></el-col><el-col :span="7"><el-form-item label="Customer Name"><el-input :model-value="selectedCustomer?.shortName||''" readonly placeholder="Press Enter to display"/></el-form-item></el-col><el-col :span="6"><el-form-item label="Payment Method"><el-select v-model="form.settlementMethod"><el-option label="Cash" value="Cash"/><el-option label="Credit" value="Credit"/></el-select></el-form-item></el-col></el-row><el-row :gutter="12"><el-col :span="16"><el-form-item label="Phone"><el-input class="customer-phone-input" type="textarea" :autosize="{minRows:1,maxRows:2}" resize="none" :model-value="selectedCustomer?.phone||selectedCustomer?.mobile||''" readonly placeholder="Press Enter to display all phone numbers"/></el-form-item></el-col><el-col :span="8"><el-form-item label="Salesperson"><el-select v-model="form.salespersonId" clearable filterable placeholder="Optional" style="width:100%"><el-option v-for="e in salespeople" :key="e.id" :label="`${e.code} ${e.name}`" :value="e.id"/></el-select></el-form-item></el-col></el-row>
<el-collapse class="optional-product-search"><el-collapse-item title="Do not know the product code? Expand category or name search" name="product-search"><el-form-item label="Product Categories"><div class="product-filters"><el-select v-model="productParentId" clearable filterable placeholder="Select manufacturer/category" @change="chooseProductParent"><el-option v-for="c in categories" :key="c.id" :label="`${c.code} ${c.name}(${c.productCount} items)`" :value="c.id"/></el-select><el-select v-model="productCategoryId" clearable filterable placeholder="Step 2: Select Subcategory" :disabled="!productParentId" @change="chooseProductCategory"><el-option v-for="c in productChildren" :key="c.id" :label="`${c.code} ${c.name}(${c.productCount} items)`" :value="c.id"/></el-select></div></el-form-item>
<el-form-item label="Name Search"><div class="product-picker"><el-input v-model="productKeyword" clearable placeholder="Enter a name or partial code" @keyup.enter="searchProducts(true)"/><el-button :loading="productLoading" @click="searchProducts(false)">Search All Products</el-button><el-select v-model="productId" filterable placeholder="Select a product from results" :loading="productLoading"><el-option v-for="p in products" :key="p.id" :label="`${p.skuCode} ${p.productName}`" :value="p.id"/></el-select><el-button type="primary" plain :disabled="!productId" @click="addProduct">Add</el-button></div><div class="picker-hint">Common action: enter the exact product code below and press Enter.</div></el-form-item></el-collapse-item></el-collapse></el-form>
<el-table :data="form.items" border class="sales-items-table"><el-table-column label="Code" width="105"><template #default="s"><el-input v-model="s.row.skuCode" class="sku-code-input" placeholder="Enter Code" @keyup.enter="resolveProductCode(s.row,s.$index)"/></template></el-table-column><el-table-column prop="productName" label="Product / Specification" min-width="160"/><el-table-column label="Current Stock" width="72"><template #default="s"><span :class="Number(s.row.currentStock)<Number(s.row.quantity)?'stock-warning':''">{{s.row.currentStock??'-'}}</span></template></el-table-column><el-table-column label="Package Size" width="82"><template #default="s"><el-input-number v-model="s.row.packageSpec" :disabled="!s.row.skuId" :min="0" :precision="2" :controls="false"/></template></el-table-column><el-table-column label="Packages" width="68"><template #default="s"><el-input-number v-model="s.row.packageCount" :disabled="!s.row.skuId" :min="0" :precision="2" :controls="false"/></template></el-table-column><el-table-column label="Package Unit" width="80"><template #default="s"><el-input v-model="s.row.packageUnit" :disabled="!s.row.skuId"/></template></el-table-column><el-table-column label="Quantity" width="86"><template #default="s"><el-input-number v-model="s.row.quantity" class="quantity-input" :disabled="!s.row.skuId" :precision="2" :controls="false" @keyup.enter="focusPrice(s.$index)"/></template></el-table-column><el-table-column prop="salesUnit" label="Unit" width="52"/><el-table-column label="Unit Price" width="90"><template #default="s"><el-input-number v-model="s.row.unitPrice" class="unit-price-input" :disabled="!s.row.skuId" :precision="2" :controls="false" :class="salePriceClass(s.row)" @keyup.enter="finishItem(s.$index)"/></template></el-table-column><el-table-column label="Reference Price" width="72"><template #default="s">{{s.row.skuId?Number(s.row.referencePrice).toFixed(2):'—'}}</template></el-table-column><el-table-column label="Amount" width="82"><template #default="s">{{s.row.skuId?(s.row.quantity*s.row.unitPrice).toFixed(2):'—'}}</template></el-table-column><el-table-column label="Notes" width="90"><template #default="s"><el-input v-model="s.row.remark" :disabled="!s.row.skuId" @keyup.enter="finishItem(s.$index)"/></template></el-table-column><el-table-column label="Actions" width="52"><template #default="s"><el-button v-if="s.row.skuId" link type="danger" @click="form.items.splice(s.$index,1);ensureBlankRow()">Delete</el-button></template></el-table-column></el-table>
<div class="order-total">Total: ¥ {{total.toFixed(2)}}</div><el-form label-width="90px"><el-form-item label="Notes"><el-input v-model="form.remark"/></el-form-item></el-form><template #footer><el-button @click="dialog=false">Cancel</el-button><el-button type="primary" @click="save">{{editingId?'Save Changes':copySourceNo?'Create New Draft':'SaveDraft'}}</el-button></template></el-dialog>
<el-dialog v-model="detailDialog" :title="`Sales Order Print Preview ${detail?.orderNo||''}`" width="980px" append-to-body class="sales-detail-dialog"><div class="print-preview-toolbar"><div><el-tag v-if="detail?.printedAt" type="warning">Printed {{detail.printCount}} times</el-tag><el-tag v-if="detail?.dispatchApproved" type="success">Approved / Dispatched</el-tag></div><el-button @click="printSettingsDialog=true">Print Settings</el-button></div><el-alert v-if="detail" :title="`Entry: ${detail.createdByName} ${String(detail.createdAt).replace('T',' ')}; Edit: ${detail.updatedByName} ${String(detail.updatedAt).replace('T',' ')}; Print: ${detail.printedByName||'Not Printed'} ${detail.printedAt?String(detail.printedAt).replace('T',' '):''}; Approve: ${detail.dispatchApprovedByName||'Not Approved'} ${detail.dispatchApprovedAt?String(detail.dispatchApprovedAt).replace('T',' '):''}`" type="info" :closable="false"/><el-collapse v-if="detail?.printHistory?.length" class="print-history"><el-collapse-item :title="`Print History (${detail.printHistory.length} times)`" name="history"><el-table :data="detail.printHistory" size="small" border><el-table-column prop="printNo" label="Print No." width="70"/><el-table-column label="Type" width="100"><template #default="s"><el-tag :type="s.row.printKind==='FIRST_PRINT'?'success':'warning'" size="small">{{printKindText(s.row.printKind)}}</el-tag></template></el-table-column><el-table-column prop="printedByName" label="Printed By" width="120"/><el-table-column label="Printed At" width="190"><template #default="s">{{String(s.row.printedAt).replace('T',' ')}}</template></el-table-column><el-table-column label="Reprint Reason" min-width="220"><template #default="s">{{s.row.reason||'—'}}</template></el-table-column></el-table></el-collapse-item></el-collapse><div v-loading="detailLoading" class="sales-print-host"><SalesOrderPrint v-if="detail" :detail="detail" type="delivery" :settings="printSettings"/></div><template #footer><el-button @click="detailDialog=false">Close</el-button><el-button :disabled="!detail" @click="exportOrder">Export Line Items CSV</el-button><el-button :disabled="!detail||detail.status==='VOIDED'" @click="printOrder">Open System Print</el-button><el-button type="success" :disabled="!detail||detail.status==='VOIDED'" @click="confirmPrintSuccess">{{detail?.printedAt?'Confirm Successful Reprint':'Confirm Print and Deduct Stock'}}</el-button></template></el-dialog>
<el-dialog v-model="printSettingsDialog" title="Delivery NotePrint Settings" width="560px" append-to-body><el-form label-width="120px"><el-form-item label="Company Header"><el-input v-model="printSettings.companyName" clearable placeholder="Leave blank to hide"/></el-form-item><el-form-item label="Paper"><el-select v-model="printSettings.paperSize"><el-option label="Continuous Paper 241 × 140 mm (Recommended)" value="CONTINUOUS_241_140"/><el-option label="A4( (backup)" value="A4"/><el-option label="A5( (backup)" value="A5"/></el-select></el-form-item><el-form-item label="Orientation"><el-radio-group v-model="printSettings.orientation"><el-radio value="landscape">Landscape</el-radio><el-radio value="portrait">Portrait</el-radio></el-radio-group></el-form-item><el-form-item label="Print Content"><el-checkbox v-model="printSettings.showPhone">Customer Phone</el-checkbox><el-checkbox v-model="printSettings.showPrice">Unit Price and amount</el-checkbox><el-checkbox v-model="printSettings.showRemark">Notes</el-checkbox></el-form-item></el-form><el-alert title="The default format is continuous-feed paper. The first confirmed print deducts stock; reprints do not." type="info" :closable="false"/><template #footer><el-button @click="printSettingsDialog=false">Cancel</el-button><el-button type="primary" @click="savePrintSettings">Save Settings</el-button></template></el-dialog>
</section></template>
